window.blockedBehindMarking=()=>{const target=scene.meshes.find(m=>m.metadata?.interactionTargetId==='NX-C01-STOP');const point=pointFor(target),rect=document.querySelector('canvas').getBoundingClientRect();const center=scene.pick(point.clientX-rect.left,point.clientY-rect.top).pickedPoint;const direction=scene.activeCamera.position.subtract(center).normalize();const make=(name,distance,componentId)=>{const box=MeshBuilder.CreateBox(name,{size:.025},scene);box.scaling.z=.02;box.position.copyFrom(center.add(direction.scale(distance)));box.lookAt(scene.activeCamera.position);box.metadata={componentId};box.computeWorldMatrix(true);return box;};const marking=make('test marking',.009,'nxstage-control-panel'),barrier=make('test barrier',.005,'other-component');const count=actions.length;const result=window.pointerPressTarget('NX-C01-STOP',95);const emitted=actions.slice(count);marking.dispose();barrier.dispose();return {result,emitted};};
window.contextLossDuringPress=async()=>{const canvas=document.querySelector('canvas');const target=scene.meshes.find(m=>m.metadata?.interactionTargetId==='NX-C01-STOP');const extension=scene.getEngine()._gl.getExtension('WEBGL_lose_context');if(!extension)throw Error('WEBGL_lose_context unavailable');window.lostContextExtension=extension;const point=pointFor(target),before=target.position.asArray(),count=actions.length;canvas.dispatchEvent(new PointerEvent('pointerdown',{...point,bubbles:true,pointerId:97,button:0,buttons:1}));const pressed=runtime.getState().pressedInteractionTargetId;const lost=new Promise(resolve=>canvas.addEventListener('webglcontextlost',resolve,{once:true}));extension.loseContext();await lost;const state=runtime.getState(),after=target.position.asArray();return {pressed,active:state.pressedInteractionTargetId,phase:state.phase,before,after,actions:actions.slice(count)};};
