window.cyclerState=()=>{const part=scene.meshes.find(m=>m.metadata?.interactionTargetId==='NX-C01-STOP');part.computeWorldMatrix(true);return {translation:runtime.getState().transforms['nxstage-cycler-door']?.translationX,world:part.getBoundingInfo().boundingBox.centerWorld.asArray()};};
