window.restoreHandle=(rotation,sequence)=>{const transforms=Object.fromEntries(manifest.components.map(component=>[component.componentId,{rotationY:component.componentId==='nxstage-cycler-handle'?rotation:0,translationX:0}]));runtime.applyAuthoritativeState({modelVersionId:manifest.modelVersionId,releaseBindingId:manifest.releaseBindingId,sequence,nextSequence:sequence+1,transforms,scorePoints:0,completed:false,allowedActions:[]});scene.render();return window.handleState();};
window.sampleHandleLift=async()=>{const engine=scene.getEngine();engine.stopRenderLoop();const original=window.requestAnimationFrame,callbacks=[];window.requestAnimationFrame=callback=>{callbacks.push(callback);return 1000000000+callbacks.length;};try{const positions=[window.handleState().world[1]];runtime.activateInteractionTarget('NX-C04-CYCLER-HANDLE');await new Promise(resolve=>setTimeout(resolve,150));const advance=offset=>{const pending=callbacks.splice(0);for(const callback of pending)callback(performance.now()+offset);positions.push(window.handleState().world[1]);};advance(0);advance(175);advance(500);return positions;}finally{window.requestAnimationFrame=original;engine.runRenderLoop(()=>scene.render());}};
window.clickCyclerPull=()=>{const canvas=document.querySelector('canvas');scene.render();const rect=canvas.getBoundingClientRect();const target=scene.meshes.find(m=>m.metadata?.interactionTargetId==='NX-C03-CYCLER-DOOR');const center=pointFor(target);let point;for(let y=-100;y<=100&&!point;y+=3)for(let x=-120;x<=120;x+=3){const hit=scene.pick(center.clientX+x-rect.left,center.clientY+y-rect.top);if(hit?.pickedMesh?.metadata?.interactionTargetId==='NX-C03-CYCLER-DOOR'){point={clientX:center.clientX+x,clientY:center.clientY+y};break;}}if(!point)return {found:false,center};canvas.dispatchEvent(new PointerEvent('pointerdown',{...point,bubbles:true,pointerId:77,button:0,buttons:1}));const pressed=runtime.getState().pressedInteractionTargetId;canvas.dispatchEvent(new PointerEvent('pointerup',{...point,bubbles:true,pointerId:77,button:0,buttons:0}));return {found:true,point,pressed};};
window.clickCyclerHandle=()=>{const canvas=document.querySelector('canvas');scene.render();const rect=canvas.getBoundingClientRect();const target=scene.meshes.find(m=>m.metadata?.interactionTargetId==='NX-C04-CYCLER-HANDLE');const center=pointFor(target);let point;for(let y=-100;y<=100&&!point;y+=3)for(let x=-120;x<=120;x+=3){const hit=scene.pick(center.clientX+x-rect.left,center.clientY+y-rect.top);if(hit?.pickedMesh?.metadata?.interactionTargetId==='NX-C04-CYCLER-HANDLE'){point={clientX:center.clientX+x,clientY:center.clientY+y};break;}}if(!point)return {found:false,center};canvas.dispatchEvent(new PointerEvent('pointerdown',{...point,bubbles:true,pointerId:79,button:0,buttons:1}));const pressed=runtime.getState().pressedInteractionTargetId;canvas.dispatchEvent(new PointerEvent('pointerup',{...point,bubbles:true,pointerId:79,button:0,buttons:0}));return {found:true,point,pressed};};
window.dragCyclerHandle=(point,cancel)=>{const canvas=document.querySelector('canvas');const count=actions.length;const event=(type,dy,buttons)=>canvas.dispatchEvent(new PointerEvent(type,{...point,clientY:point.clientY+dy,bubbles:true,pointerId:80,button:0,buttons}));event('pointerdown',0,1);const pressed=runtime.getState().pressedInteractionTargetId;event('pointermove',-90,1);const during=runtime.getState().transforms['nxstage-cycler-handle'].rotationY;event(cancel?'pointercancel':'pointerup',-90,0);return {pressed,during,after:runtime.getState().transforms['nxstage-cycler-handle'].rotationY,actions:actions.slice(count)};};
window.dragCyclerPull=(point,cancel)=>{const canvas=document.querySelector('canvas');const count=actions.length;const event=(type,dy,buttons)=>canvas.dispatchEvent(new PointerEvent(type,{...point,clientY:point.clientY+dy,bubbles:true,pointerId:78,button:0,buttons}));event('pointerdown',0,1);const pressed=runtime.getState().pressedInteractionTargetId;event('pointermove',100,1);const during=runtime.getState().transforms['nxstage-cycler-door'].translationX;event(cancel?'pointercancel':'pointerup',100,0);return {pressed,during,after:runtime.getState().transforms['nxstage-cycler-door'].translationX,actions:actions.slice(count)};};
