window.pressDirection=(id)=>{const target=scene.meshes.find(m=>m.metadata?.interactionTargetId===id);const point=pointFor(target);target.computeWorldMatrix(true);const before=target.getBoundingInfo().boundingBox.centerWorld.clone();const canvas=document.querySelector('canvas');canvas.dispatchEvent(new PointerEvent('pointerdown',{...point,bubbles:true,pointerId:80,button:0,buttons:1}));target.computeWorldMatrix(true);const after=target.getBoundingInfo().boundingBox.centerWorld.clone();canvas.dispatchEvent(new PointerEvent('pointerup',{...point,bubbles:true,pointerId:80,button:0,buttons:0}));return {id,displacement:after.subtract(before).asArray(),towardCamera:Vector3.Dot(after.subtract(before),scene.activeCamera.position.subtract(before).normalize())};};
